# Generated by liza toolchain configure.
# Source this file before running liza init or liza agent commands.
export PATH='<INSTALL>':"$PATH"
export LIZA_ENABLE_SCIP_SEARCH='1'
export LIZA_ENABLE_STACKLIT='1'
# Register Liza shell completions for interactive shells.
case "$-" in
  *i*)
    if command -v liza >/dev/null 2>&1; then
      if [ -n "${BASH_VERSION:-}" ]; then
        eval "$(liza completion bash 2>/dev/null)"
      elif [ -n "${ZSH_VERSION:-}" ]; then
        autoload -Uz compinit 2>/dev/null || true; compinit -i 2>/dev/null || true; eval "$(liza completion zsh 2>/dev/null)"
      fi
    fi
    ;;
esac
